from solution import get_max_sum


def test_issue_example_60():
    """Example: f(n)=max(f(n/2)+f(n/3)+f(n/4)+f(n/5), n) gives get_max_sum(60)==106."""
    assert get_max_sum(60) == 106  # f30=44, f20=28, f15=18, f12=16; 44+28+18+16=106 > 60


def test_issue_zero():
    """f(n)=max(f(n/2)+f(n/3)+f(n/4)+f(n/5), n) gives get_max_sum(0)==0."""
    assert get_max_sum(0) == 0  # 0+0+0+0=0; max(0, 0)=0


