    """f(n)=max(f(n/2)+f(n/3)+f(n/4)+f(n/5), n) gives get_max_sum(4)==4."""
    assert get_max_sum(4) == 4  # f2=2, f1=1, f1=1, f0=0; 2+1+1+0=4; max(4, 4)=4


