    """f(n)=max(f(n/2)+f(n/3)+f(n/4)+f(n/5), n) gives get_max_sum(30)==44."""
    assert get_max_sum(30) == 44  # f15=18, f10=12, f7=7, f6=7; 18+12+7+7=44; max(44, 30)=44


def test_issue_large_hundred():
    """f(n)=max(f(n/2)+f(n/3)+f(n/4)+f(n/5), n) gives get_max_sum(100)==200."""
    assert get_max_sum(100) == 200  # f50=86, f33=49, f25=37, f20=28; 86+49+37+28=200; max(200, 100)=200


def test_contract_lower_bound_split():
    """f(n)=max(..., n) implies the result is never below n."""
    assert get_max_sum(24) >= 24  # f12=16, f8=9, f6=7, f4=4; 16+9+7+4=36 >= 24


def test_contract_lower_bound_identity():
    """f(n)=max(..., n) implies the result is never below n."""
    assert get_max_sum(2) >= 2  # f1=1, f0=0, f0=0, f0=0; 1+0+0+0=1; max(1, 2)=2 >= 2


def test_contract_returns_int():
    """Example get_max_sum(60)==106 implies the result is an int."""
    assert isinstance(get_max_sum(60), int)  # 44+28+18+16=106, an int
